patches.content:
Loader {
    id: wifiAppletMenuBridge
    anchors.fill: parent
    Component.onCompleted: setSource(Quickshell.shellPath("mod/indicator_tools/AppletMenuBridge.qml"), { "appletId": "nm-applet", "styledMenu": true })
}

Loader {
    id: bluetoothAppletMenuBridge
    anchors.fill: parent
    Component.onCompleted: setSource(Quickshell.shellPath("mod/indicator_tools/AppletMenuBridge.qml"), { "appletId": "blueman", "styledMenu": true })
}

Loader {
    id: wifiAppletMenuBridge
    anchors.fill: parent
    Component.onCompleted: setSource(Quickshell.shellPath("mod/indicator_tools/AppletMenuBridge.qml"), { "appletId": "nm-applet", "styledMenu": true })
}

Loader {
    id: bluetoothAppletMenuBridge
    anchors.fill: parent
    Component.onCompleted: setSource(Quickshell.shellPath("mod/indicator_tools/AppletMenuBridge.qml"), { "appletId": "blueman", "styledMenu": true })
}

altAction: event => {
    const wifiPoint = wifiAppletMenuBridge.mapFromItem(rightSidebarButton, event.x, event.y)
    if (wifiAppletMenuBridge.parent.visible && wifiAppletMenuBridge.contains(wifiPoint)) {
        bluetoothAppletMenuBridge.item?.closeStyledMenu()
        wifiAppletMenuBridge.item?.toggleStyledMenu()
        return
    }
    const bluetoothPoint = bluetoothAppletMenuBridge.mapFromItem(rightSidebarButton, event.x, event.y)
    if (bluetoothAppletMenuBridge.parent.visible && bluetoothAppletMenuBridge.contains(bluetoothPoint)) {
        wifiAppletMenuBridge.item?.closeStyledMenu()
        bluetoothAppletMenuBridge.item?.toggleStyledMenu()
    }
}

altAction: event => {
