}

Binding {
    target: root
    property: "pinnedItems"
    value: TrayService.pinnedItems.filter(item => item.id !== "nm-applet" && item.id !== "blueman")
}

Binding {
    target: root
    property: "unpinnedItems"
    value: TrayService.unpinnedItems.filter(item => item.id !== "nm-applet" && item.id !== "blueman")
}

Binding {
    target: traySeparator
    property: "visible"
    value: root.showSeparator && (root.pinnedItems.length > 0 || root.unpinnedItems.length > 0)
}
